-- Generated by content-pipeline. Real pre-2023 human texts + matched AI twins.
INSERT OR REPLACE INTO days (date, day_number, cards_json) VALUES
  ('2026-09-04', 1, '[{"id":1,"platform":"x","context_label":{"he":"פוסט ב-X על תהליכי גיוס","en":"Post on X about hiring processes"},"text":"We optimized our hiring funnel so much that we started rejecting great engineers for bad whiteboard days. Took us two years to notice the pattern.","is_ai":true,"tell":{"he":"האנקדוטה על ''שנתיים לגלות את הדפוס'' מומצאת ונקייה מדי - AI מוסיף לקח מסודר לכל סיפור.","en":"The ''two years to notice the pattern'' anecdote is invented and too tidy. AI attaches a clean lesson to every story."}},{"id":2,"platform":"linkedin","context_label":{"he":"תגובה בלינקדאין על פוסט בנושא סטארטאפים שנסגרים","en":"LinkedIn comment on a post about startup postmortems"},"text":"It''s often hard to know why a startup failed. For example, if you released something but got few sales, it''s hard to know if the product wasn''t executed well enough, or your sales & marketing were weak, or there''s simply no market. Would a couple more iterations have brought success? You can never be sure.","is_ai":false,"tell":{"he":"נגמר בשאלה פתוחה בלי מענה. AI סוגר מעגלים, בני אדם משאירים אותם תלויים.","en":"Ends on an open question with no resolution. AI closes loops; humans leave them hanging."}},{"id":3,"platform":"x","context_label":{"he":"תגובה ב-X לשרשור על משכורות מפתחים","en":"Reply on X to a thread about developer salaries"},"text":"Companies are cheap, and lots of hiring managers believe they can get lucky and find that one guy that is a rockstar programmer but doesn''t know it, and thus can be had for cheap.","is_ai":false,"tell":{"he":"ציניות עם פסיכולוגיה ספציפית (''רוקסטאר שלא יודע שהוא'') - מודלים מכלילים, בני אדם מרכלים.","en":"Cynical, specific psychology (''rockstar who doesn''t know it''). Models generalize, humans gossip."}},{"id":4,"platform":"x","context_label":{"he":"פוסט ב-X על תהליכי גיוס","en":"Post on X about hiring processes"},"text":"The problem is the hiring process tests for your ability to make it through the hiring process, not for your ability to actually do the job.","is_ai":false,"tell":{"he":"משפט חד עם טוויסט - זהב של פורומים אנושיים. AI כמעט לא מייצר משפט כל כך נצטט בלי ריפוד.","en":"A quotable twist with zero padding. AI rarely lands a line this clean without hedging."}},{"id":5,"platform":"x","context_label":{"he":"תגובה ב-X לשרשור על משכורות מפתחים","en":"Reply on X to a thread about developer salaries"},"text":"A lot of companies are not really hiring, they are lottery hunting. They want senior output at junior pay and genuinely believe the right person is out there desperate enough to take it.","is_ai":true,"tell":{"he":"מסביר את המטאפורה של עצמו (''סניור במחיר ג''וניור'') מיד אחרי שהוא יוצר אותה. בני אדם סומכים על התמונה וממשיכים הלאה.","en":"Explains its own metaphor right after making it. Humans trust the image and move on."}}]'),
  ('2026-09-05', 2, '[{"id":1,"platform":"linkedin","context_label":{"he":"תגובה בלינקדאין על פוסט בנושא סטארטאפים שנסגרים","en":"LinkedIn comment on a post about startup postmortems"},"text":"The honest answer about why most startups fail is that nobody knows, including the founders. I shut down my first company in 2019 and I still could not tell you if it was the market or our execution. Probably both, in proportions I will never measure.","is_ai":true,"tell":{"he":"גם הווידוי האישי (''סגרתי ב-2019'') מנוסח במשפטים מושלמים ומאוזנים - אף אחד לא כותב ככה בכאב.","en":"Even the personal confession (''shut down in 2019'') comes in perfectly balanced sentences. Nobody writes like that from pain."}},{"id":2,"platform":"x","context_label":{"he":"פוסט ב-X על יזמים שנכשלו","en":"Post on X about failed founders"},"text":"They write melodramatic postmortems on Medium which fail to identify why exactly their startup failed. Afterward, they either a) do another startup or b) join an established company, depending on how jaded they are from the experience.","is_ai":false,"tell":{"he":"המבנה a) b) באמצע משפט והסטירה לפוסט-מורטמים ב-Medium - ניסיון חי, לא סיכום.","en":"The a) b) list mid-sentence and the jab at Medium postmortems is lived experience, not summary."}},{"id":3,"platform":"x","context_label":{"he":"תגובה ב-X לשרשור על סטארטאפים שנסגרו","en":"Reply on X to a thread about failed startups"},"text":"After my startup went under I realized my technical skills had gone soft from two years of doing everything except coding. Spent six months grinding through projects before anyone would hire me. Thinking about trying again in a few years.","is_ai":true,"tell":{"he":"הקשת מסודרת מדי: כישלון, ענווה, בנייה מחדש, תקווה. סיפורי התאוששות אמיתיים משוטטים.","en":"The arc is too neat: failure, humility, rebuild, hope. Real recovery stories wander."}},{"id":4,"platform":"x","context_label":{"he":"תגובה ב-X לשרשור על סטארטאפים שנסגרו","en":"Reply on X to a thread about failed startups"},"text":"Personally I wasn''t a great coder after my startup failed (right after college). So I went to Fullstack Academy, and then got a job as a web developer. I plan on taking another stab at it once I get some more experience though.","is_ai":false,"tell":{"he":"מזכיר בוטקאמפ ספציפי ותוכנית לא גמורה. AI ממציא החלמות מעורפלות יותר.","en":"Names a specific bootcamp and an unfinished plan. AI invents vaguer recoveries."}},{"id":5,"platform":"x","context_label":{"he":"פוסט ב-X על יזמים שנכשלו","en":"Post on X about failed founders"},"text":"Every failed startup produces the same Medium post. Long on feelings, short on numbers. Then the founder either raises again on the strength of the lesson or disappears into a big company for five years.","is_ai":true,"tell":{"he":"ציניות עם דקדוק מושלם ואפס שגיאות כתיב. ציניות אנושית מבולגנת יותר.","en":"Sarcasm with perfect grammar and no typos. Human snark is usually sloppier."}}]'),
  ('2026-09-06', 3, '[{"id":1,"platform":"whatsapp","context_label":{"he":"הודעה בקבוצת וואטסאפ של עובדי הייטק על פיטורים","en":"WhatsApp message in a tech workers group about layoffs"},"text":"my cousin got hit in the san diego round. 11 years there, gone in a 10 minute call. thats how it goes now","is_ai":true,"tell":{"he":"כמעט עובר - אבל ''בן הדוד שלי נפל בסבב בסן דייגו'' מנוסח חלק מדי לצ''אט, בלי שגיאה אחת.","en":"Almost passes, but ''gone in a 10 minute call'' is polished clean. Real group-chat bad news comes with typos."}},{"id":2,"platform":"linkedin","context_label":{"he":"תגובה בלינקדאין על פוסט בנושא פיטורים שקטים","en":"LinkedIn comment on a post about quiet layoffs"},"text":"This is how headcount reduction usually happens in practice. No announcement, just a hiring freeze and goals that quietly tighten until people leave on their own. The best ones always have options first.","is_ai":true,"tell":{"he":"מסביר את המנגנון בניקיון כמו תרגיל בבית ספר לעסקים. בני אדם מרמזים ומניחים שאתה יודע.","en":"Explains the mechanism cleanly like a business school case. Humans hint and assume you know."}},{"id":3,"platform":"linkedin","context_label":{"he":"תגובה בלינקדאין על פוסט בנושא פיטורים שקטים","en":"LinkedIn comment on a post about quiet layoffs"},"text":"Maybe it''s a way to reduce head count without having a have a layoff? If you just have to \"make your numbers\" (and you don''t care the best will leave first) it might be a viable strategy in the short term ...","is_ai":false,"tell":{"he":"שגיאת הכתיב ''have a have a'' שרדה. AI לא מכפיל מילים, בני אדם עייפים כן.","en":"The typo ''have a have a'' survived. AI doesn''t double words; tired humans do."}},{"id":4,"platform":"whatsapp","context_label":{"he":"הודעה בקבוצת וואטסאפ של עובדי הייטק על פיטורים","en":"WhatsApp message in a tech workers group about layoffs"},"text":"come on Qualcomm is a US company, just doing what everybody else does the best: layoff when the diaper is wet.","is_ai":false,"tell":{"he":"אותיות קטנות, בלי הקדמה, ו''כשהחיתול רטוב'' - שום מודל לא כותב את המטאפורה הזו.","en":"Lowercase, no preamble, and ''when the diaper is wet''. No model writes that metaphor."}},{"id":5,"platform":"linkedin","context_label":{"he":"תגובה בלינקדאין על פוסט בנושא לשרוד פיטורים","en":"LinkedIn comment on a post about surviving layoffs"},"text":"The last time I survived layoffs, it took me longer to find a new job than my laid-off peers. I''ll always be grateful to have a place to go that sends me a check for the privilege of my company, even if I hate going there.","is_ai":false,"tell":{"he":"הכרת תודה מרירה (''צ''ק בתמורה לזכות החברה שלי'') - מורכבות רגשית שמודלים משטחים.","en":"Bitter gratitude (''a check for the privilege of my company'') is emotionally complex in a way models flatten."}}]'),
  ('2026-09-07', 4, '[{"id":1,"platform":"linkedin","context_label":{"he":"תגובה בלינקדאין על פוסט בנושא ביטול ישיבות","en":"LinkedIn comment on a post about killing meetings"},"text":"I worked at a place that banned meetings on Wednesdays. People just crammed five hours of calls into Tuesday and Thursday. The calendar was not the problem, the culture was.","is_ai":true,"tell":{"he":"המשפט האחרון הוא מדבקת פגוש. גרסאות אמיתיות של הסיפור הזה נגמרות במה שקרה אחר כך בפועל.","en":"The last sentence is a bumper sticker. Real versions of this story end with what actually happened next."}},{"id":2,"platform":"linkedin","context_label":{"he":"תגובה בלינקדאין על פוסט בנושא לשרוד פיטורים","en":"LinkedIn comment on a post about surviving layoffs"},"text":"People assume the laid off colleagues got the worst of it. Mine mostly landed within a quarter, severance in hand. Those of us left behind absorbed their work and got a pizza budget for it.","is_ai":true,"tell":{"he":"כל משפט באותו אורך וצורה. ניפוץ זעם אנושי מגוון בקצב.","en":"Every sentence is the same length and shape. Human venting varies its rhythm."}},{"id":3,"platform":"whatsapp","context_label":{"he":"הודעה בקבוצת וואטסאפ על הודעת פיטורים של מנכ\"ל","en":"WhatsApp message in a group about a CEO''s layoff announcement"},"text":"He should have spent time talking about the severance. Honestly, if I was going through a layoff, that''s all I''d care about at that point.","is_ai":false,"tell":{"he":"אפס הקשר, ישר לפיצויים. אנשים אמיתיים בקבוצות מדלגים על ההקדמה.","en":"Zero context, straight to severance. Real people in group chats skip the preamble."}},{"id":4,"platform":"linkedin","context_label":{"he":"תגובה בלינקדאין על פוסט בנושא ביטול ישיבות","en":"LinkedIn comment on a post about killing meetings"},"text":"Agreed. And we need good meetings. But we shouldn''t assume that no meetings is better than good meetings. Standing meetings work. When anyone (non handicapped) wants to sit down, it''s a sign the meeting is going too long.","is_ai":false,"tell":{"he":"הסוגריים המגושמים ''(non handicapped)'' - גידוד אנושי ששום מודל לא היה מוסיף.","en":"The awkward ''(non handicapped)'' parenthetical is a human hedge no model would add."}},{"id":5,"platform":"whatsapp","context_label":{"he":"תגובה בקבוצת וואטסאפ על מקום עבודה רעיל","en":"WhatsApp reply in a group about a toxic workplace"},"text":"honestly the best career advice i ever got was quit faster. stayed 2 years too long at a place that made me miserable and the raise i got after leaving was 40 percent","is_ai":true,"tell":{"he":"פרט ה-''40 אחוז העלאה'' עובד קשה מדי - AI מוסיף מספר כדי להישמע אמיתי.","en":"The ''40 percent raise'' detail is doing too much work. AI adds a number to sound real."}}]'),
  ('2026-09-08', 5, '[{"id":1,"platform":"whatsapp","context_label":{"he":"תגובה בקבוצת וואטסאפ על מקום עבודה רעיל","en":"WhatsApp reply in a group about a toxic workplace"},"text":"Yes, run! Do not keep satisfied with a toxic situation, that''s a fast-lane to burnout. edit: alternatively, consider some time off, might be you''re already overworked and would see things from a different perspective after some rest.","is_ai":false,"tell":{"he":"התיקון העצמי ''edit:'' באמצע הודעה - התנהגות של פורום, לא טקסט מופק.","en":"The ''edit:'' self-correction mid-message is forum behavior, not generated text."}},{"id":2,"platform":"x","context_label":{"he":"פוסט ב-X על עצות נגד שחיקה","en":"Post on X about burnout advice"},"text":"How-to-beat-burnout posts often have different answers. I think that''s because what causes burnout (how to de-stress) is a very personal thing, something that differs person to person. So hard to generalize.","is_ai":false,"tell":{"he":"ניסוח מעט מגושם (''differs person to person'') עם נקודה אמיתית - AI חלק יותר וריק יותר.","en":"Slightly clunky phrasing (''differs person to person'') with a real point. AI is smoother and emptier."}},{"id":3,"platform":"whatsapp","context_label":{"he":"הודעה בקבוצת וואטסאפ של מפתחים על להישאר רלוונטיים","en":"WhatsApp message in a developers group about keeping up"},"text":"felt this. spent my twenties learning every new framework the week it dropped. now im 34 and i just want to be good at one thing and see my kids before bedtime","is_ai":true,"tell":{"he":"מחקה את הרגיסטר יפה, אבל ''הביקורות שלי דווקא השתפרו'' הוא סוף מסודר מדי לשיחת וואטסאפ.","en":"Mimics the register well, but ''my reviews actually improved'' is too neat an ending for a group chat."}},{"id":4,"platform":"x","context_label":{"he":"פוסט ב-X על עצות נגד שחיקה","en":"Post on X about burnout advice"},"text":"Burnout advice fails because it treats one disease with many causes. Mine was not overwork, it was working on things I did not believe in. No amount of yoga fixes that.","is_ai":true,"tell":{"he":"היגיון מקבילי מושלם על למה עצות נכשלות. בני אדם פשוט אומרים מה עבד להם.","en":"Perfectly parallel reasoning about why advice fails. Humans just say what worked for them."}},{"id":5,"platform":"whatsapp","context_label":{"he":"הודעה בקבוצת וואטסאפ של מפתחים על להישאר רלוונטיים","en":"WhatsApp message in a developers group about keeping up"},"text":"OK, that''s good thought, hehe. I am forcing myself to improve a lot, not for this current job, but to catch up with the community. I am not sure I can continue doing it after 30, cause too many things to learn and gonna burn out myself.","is_ai":false,"tell":{"he":"''hehe'', דקדוק שבור וחרדה מגיל 30 - כנות מבולגנת היא אנושית.","en":"''hehe'', broken grammar, and anxiety about turning 30. Messy sincerity is human."}}]'),
  ('2026-09-09', 6, '[{"id":1,"platform":"x","context_label":{"he":"פוסט ב-X על ללמד ילדים תכנות","en":"Post on X about teaching kids to code"},"text":"JS will probably mess up my kid''s mind as much as ruby. My choices for intro programming language would probably be Haskell and Coffeescript - both has a simple but coherent set of concepts and a straightforward syntax designed around those concepts.","is_ai":false,"tell":{"he":"שגיאת דקדוק (''both has'') ודעה נחרצת על שפות תכנות לילדים - אנושי קלאסי.","en":"Grammar error (''both has'') plus a strong opinion on kids'' programming languages. Classic human."}},{"id":2,"platform":"whatsapp","context_label":{"he":"תגובה בקבוצת וואטסאפ על שחיקה","en":"WhatsApp reply in a group about burnout"},"text":"Sounds like burnout. I take a month or 2 off for every year I work.. sometimes at the start of that break, I feel like you do, but a bit of sun on my face and some outdoors, and suddenly the desire to sit inside and code for hours, starts to return. :D","is_ai":false,"tell":{"he":"נקודה כפולה ''..'' וסמיילי '':D'' - הרגלי אינטרנט של פעם שמסמנים בן אדם אמיתי.","en":"Double period ''..'' and a '':D'' - pre-emoji internet mannerisms that mark a real person."}},{"id":3,"platform":"x","context_label":{"he":"פוסט ב-X על ללמד ילדים תכנות","en":"Post on X about teaching kids to code"},"text":"Started my son on Python at 9 and the only real problem is he now thinks indentation errors are a personal attack. Pick whatever gets them building something they care about fastest.","is_ai":true,"tell":{"he":"האנקדוטה על הילד גנרית (שגיאות הזחה כעלבון אישי). הורים אמיתיים מספרים משהו מוזר וספציפי.","en":"The kid anecdote is generic (indentation errors as personal attack). Real parents tell something weirder and more specific."}},{"id":4,"platform":"linkedin","context_label":{"he":"תגובה בלינקדאין על פוסט בנושא חברה גדולה שמשחררת קוד פתוח","en":"LinkedIn comment on a post about a big company open sourcing a project"},"text":"I have been the engineer assigned to open source a dying internal project. The goal was never adoption, it was a soft landing for the code and a press line for the blog. Real commitment looks different.","is_ai":true,"tell":{"he":"''הייתי המהנדס שהופקד על...'' - פתיח של סיפור מושלם. עדות אמיתית מתחילה באמצע.","en":"''I have been the engineer assigned to...'' - a perfectly constructed story opening. Real testimony starts in the middle."}},{"id":5,"platform":"whatsapp","context_label":{"he":"תגובה בקבוצת וואטסאפ על שחיקה","en":"WhatsApp reply in a group about burnout"},"text":"i do something similar, 3 weeks completely offline every summer. first week im twitchy and checking my phone, by week two im a different person. the code is still there when i get back, it can wait","is_ai":true,"tell":{"he":"אותיות קטנות וקז''ואל, אבל כל משפט שלם ועל-נושא. צ''אטים אמיתיים סוטים.","en":"Lowercase and casual, but every sentence is complete and on-theme. Real chats drift."}}]'),
  ('2026-09-10', 7, '[{"id":1,"platform":"whatsapp","context_label":{"he":"הודעה בקבוצת וואטסאפ של יזמים","en":"WhatsApp message in a founders group"},"text":"Good luck none the less, I am sure they identified it as a risk. - edit Bad spelling, early morning before my coffee.","is_ai":false,"tell":{"he":"התנצלות על איות לפני הקפה, ב-edit, עם מקף - פטפוט אנושי טהור.","en":"Apologizing for spelling before coffee, in an edit, with a dash. Pure human chatter."}},{"id":2,"platform":"linkedin","context_label":{"he":"תגובה בלינקדאין על פוסט בנושא משרד ביתי מול קו-וורקינג","en":"LinkedIn comment on a post about home office vs coworking"},"text":"After eight months working from home I could not tell where work ended and life began, so I tried a coworking space. Hated the noise, loved the commute ritual. Now I split the week, three days home, two there.","is_ai":true,"tell":{"he":"פוגע באותם צ''ק-פוינטים כמו הטקסטים האנושיים אבל נפתר נקי מדי. בלי קצוות פתוחים.","en":"Hits the same beats as the human texts but resolves too cleanly. No loose ends."}},{"id":3,"platform":"linkedin","context_label":{"he":"תגובה בלינקדאין על פוסט בנושא חברה גדולה שמשחררת קוד פתוח","en":"LinkedIn comment on a post about a big company open sourcing a project"},"text":"This is the usual pattern of a big company open sourcing peripheral and dying projects to appear hip, or to hope for free work. Now, let''s see if they open source an important greenfield project, then devote resources to the development of that project. Don''t count on it.","is_ai":false,"tell":{"he":"נגמר ב-''Don''t count on it'' - פסק דין קצר ותקיף. AI מעדיף סיומות מאוזנות.","en":"Ends with ''Don''t count on it'' - a blunt two-word verdict. AI prefers balanced closings."}},{"id":4,"platform":"x","context_label":{"he":"תגובה ב-X לשרשור על חברות שבונות על קוד פתוח","en":"Reply on X to a thread about companies building on open source"},"text":"How is building on top of an open source product milking it? Isn''t this increasing git''s exposure? If they didn''t want that, they should''ve used a more restrictive license.","is_ai":false,"tell":{"he":"שתי שאלות רטוריות ברצף וסטירת רישיונות - רגיסטר ויכוחי שמודלים מרככים.","en":"Two rhetorical questions in a row and a licensing jab. Models soften this argumentative register."}},{"id":5,"platform":"x","context_label":{"he":"תגובה ב-X לשרשור על חברות שבונות על קוד פתוח","en":"Reply on X to a thread about companies building on open source"},"text":"If offering a hosted version of an open tool is milking it, then every cloud company is guilty. The license allows it explicitly. That is the deal the maintainers signed up for.","is_ai":true,"tell":{"he":"טוען לשני הצדדים ונוחת בטוח. ויכוחי רישיונות אנושיים הופכים שבטיים.","en":"Argues both sides then lands safe. Human licensing debates get tribal."}}]');
DELETE FROM days WHERE date NOT IN ('2026-09-04','2026-09-05','2026-09-06','2026-09-07','2026-09-08','2026-09-09','2026-09-10');
